pub fn provider_defaults(provider: ProviderId) -> ProviderDefaults {
    match provider {
        ProviderId::Claude => ProviderDefaults {
            model_label: "Opus 5.5",
            model_id: "claude-opus-5-5",
            reasoning_effort: Some("medium"),
        },
        ProviderId::Codex => ProviderDefaults {
            model_label: "GPT-6.1 Sol",
            model_id: "gpt-6.1-sol",
            reasoning_effort: Some("medium"),
        },
        ProviderId::Cursor => ProviderDefaults {
            model_label: "Grok 4.7 (Cursor)",
            model_id: "grok-4.7-medium",
            reasoning_effort: Some("medium"),
        },
        ProviderId::Opencode => ProviderDefaults {
            model_label: "GLM-5.3-Flash",
            model_id: "openrouter/z-ai/glm-5.3-flash",
            reasoning_effort: Some("high"),
        },
        ProviderId::Grok => ProviderDefaults {
            model_label: "Grok 4.7",
            model_id: "grok-4.7",
            reasoning_effort: Some("medium"),
        },
    }
}

pub fn helper_model(provider: ProviderId) -> &'static str {
    match provider {
        ProviderId::Claude => "claude-sonnet-5-5",
        ProviderId::Codex => "gpt-6-luna",
        ProviderId::Cursor => "composer-2.5",
        ProviderId::Opencode => "openrouter/z-ai/glm-5.3-flash",
        ProviderId::Grok => "grok-4.7",
    }
}
